    var tabs = root.querySelectorAll('.gp-tab');
    tabs.forEach(function (t) {
      var label = t.textContent.replace(/\d+$/, '').trim();
      t.setAttribute('aria-pressed', label === CAT_LABEL[cat] ? 'true' : 'false');
    });
    var grid = root.querySelector('.gp-grid');
    grid.classList.add('is-switching');
