      img.width = it.tw; img.height = it.th;
      img.addEventListener('load', function () { t.classList.add('is-loaded'); });
      if (img.complete && img.naturalWidth) t.classList.add('is-loaded');
      t.appendChild(img);
      t.appendChild(el('span', 'gp-chip gp-chip--cat', CAT_LABEL[it.cat]));
